[{"location":"#Neverthrow.jl","page":"Neverthrow.jl","title":"Neverthrow.jl","text":"using Neverthrow","category":"section"},{"location":"#map_ok,-map","page":"Neverthrow.jl","title":"map_ok, map","text":"plain function application : map is an alias for map_ok \n\nsquare(x::Real) = x^2\nmap(square, Ok(2))\nmap(square, Err(\"oops\"))\n\nchaining / piping calls : map can't be used like this, use map_ok instead\n\nErr(\"oops\") |> map_ok(square)","category":"section"},{"location":"#map_err","page":"Neverthrow.jl","title":"map_err","text":"Ok(:success) |> map_err(square)\nErr(3) |> map_err(square)","category":"section"},{"location":"#unwrap_or","page":"Neverthrow.jl","title":"unwrap_or","text":"Ok(2) |> map_ok(square) |> unwrap_or(10)\nErr(\"oops\") |> map_ok(square) |> unwrap_or(10)","category":"section"},{"location":"#and_then","page":"Neverthrow.jl","title":"and_then","text":"chaining results\n\nsq(x) = Ok(x^2)\n\n(Ok(2)\n |> and_then(sq)\n |> and_then(sq))\n\n(Ok(2)\n |> and_then(sq)\n |> and_then(Err))\n\n(Ok(2)\n |> and_then(Err)\n |> and_then(sq))\n\n(Err(\"oops\")\n |> and_then(sq)\n |> and_then(sq))\n\nflattening nested results\n\nOk(Ok(42)) |> and_then(identity)","category":"section"},{"location":"#or_else","page":"Neverthrow.jl","title":"or_else","text":"recover(query_result) = or_else(query_result) do reason\n    reason === :not_found && return Ok(\"User does not exist\")\n    return Err(500)\nend\n\nrecover(Ok(\"found\"))\nrecover(Err(:not_found))\nrecover(Err(:pool_exhausted))","category":"section"},{"location":"#and_tee","page":"Neverthrow.jl","title":"and_tee","text":"log_result(x) = @info \"Got result $x\"\n\n(Ok(2)\n |> and_tee(log_result)\n |> and_then(sq))","category":"section"},{"location":"#or_tee","page":"Neverthrow.jl","title":"or_tee","text":"log_error(x) = @error \"Got error $x\"\n\n(Err(\"oops\")\n |> or_tee(log_error)\n |> and_then(sq))","category":"section"},{"location":"#and_through","page":"Neverthrow.jl","title":"and_through","text":"validate(x) = (x == :valid ? Ok() : Err(\"invalid user\"))\n\nOk(:valid) |> and_through(validate)\nOk(:invalid) |> and_through(validate)\nErr(\"no user\") |> and_through(validate)","category":"section"},{"location":"#from_throwable","page":"Neverthrow.jl","title":"from_throwable","text":"const safe_sqrt = from_throwable(sqrt)\nsafe_sqrt(2)\nsafe_sqrt(-1)","category":"section"},{"location":"#combine","page":"Neverthrow.jl","title":"combine","text":"(Ok(1), Ok(\"foo\")) |> combine\n(Ok(1), Err(\"boom\")) |> combine\n\nx = Ok(1)\ny = Ok(2)\n\ncombine(x, y) |> map_ok(splat(+))","category":"section"}]
